</script>
<template>
 <div class="layout-playback">
  <div class="playback-actions"><button type="button" :disabled="disabled" @click="emit('command',{command:'stage',stage:'exploded'})">▶ 拆解演示</button><button type="button" :disabled="disabled" @click="emit('command',{command:'stage',stage:'solid'})">↶ 反向组装</button><button type="button" :disabled="disabled" @click="emit('command',{command:'stage',stage:'xray'})">外壳透视</button><button v-if="previewing" type="button" :disabled="disabled" @click="emit('command',{command:previewState.paused?'resume':'pause'})">{{ previewState.paused ? '继续' : '暂停' }}</button><button v-if="previewing" type="button" class="return-edit" :disabled="disabled" @click="emit('edit')">返回摆放</button></div>
